CREATE TABLE IF NOT EXISTS public.talent_earnings (talent_id uuid PRIMARY KEY, pending_amount numeric(12,2) NOT NULL DEFAULT 0, available_amount numeric(12,2) NOT NULL DEFAULT 0, paid_amount numeric(12,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'NGN', updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.talent_earnings TO authenticated; GRANT ALL ON public.talent_earnings TO service_role; ALTER TABLE public.talent_earnings ENABLE ROW LEVEL SECURITY; CREATE POLICY "talent own earnings read" ON public.talent_earnings FOR SELECT TO authenticated USING (talent_id=auth.uid() OR public.is_admin()); CREATE POLICY "admin manage earnings" ON public.talent_earnings FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());
